-- gen600: 20 zone cambiate, 40 tessere
-- 7dc13681561dcd789069adec3fd99854 (833714) → 9f00b4a0a6629c664d659dac78052959 (840372)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '9f00b4a0a6629c664d659dac78052959' as combacia
from kv_store where key like 'tmp:gen600:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen600:p%')
where key='app:jsx:src'
  and md5(value) = '7dc13681561dcd789069adec3fd99854'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen600:p%') = '9f00b4a0a6629c664d659dac78052959';

update kv_store set value = '{"len":840372,"ver":"gen-6.00"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '9f00b4a0a6629c664d659dac78052959';

delete from kv_store where key like 'tmp:gen600:p%';
